import numpy as np
from scipy.optimize import curve_fit
raw=np.loadtxt('graphene.dat',delimiter='\t',converters={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))})
x,y=raw[:,0],raw[:,1]
w=1e7/x
# sort by w
o=np.argsort(w); w=w[o]; x=x[o]; y=y[o]

def lor_fwhm(t,x0,g,A,off,slope=0):
    return off+slope*(t-x0)+A*(g/2)**2/((t-x0)**2+(g/2)**2)
def lor_hwhm(t,x0,g,A,off,slope=0):
    return off+slope*(t-x0)+A*g**2/((t-x0)**2+g**2)
def gauss(t,x0,g,A,off,slope=0):
    return off+slope*(t-x0)+A*np.exp(-4*np.log(2)*(t-x0)**2/g**2)

for dom,ax in [('w',w),('x',x)]:
    print("##### domain",dom)
    for name,lo,hi,p0 in [('G',1530,1635,[1580,20,8000,6000]),('2D',2580,2760,[2670,40,7000,3000])]:
        if dom=='w':
            pass
        else:
            lo,hi=1e7/hi,1e7/lo
            p0=[1e7/p0[0],p0[1],p0[2],p0[3]]
        m=(ax>=lo)&(ax<=hi)
        t=ax[m]; yy=y[m]
        print("--",name,"np",m.sum(),"range",lo,hi)
        for fname,f in [('lor_fwhm',lor_fwhm),('lor_hwhm',lor_hwhm),('gauss',gauss)]:
            for withslope in [False,True]:
                try:
                    if withslope:
                        pf,cov=curve_fit(f,t,yy,p0=p0+[0],maxfev=200000)
                    else:
                        pf,cov=curve_fit(f,t,yy,p0=p0,maxfev=200000)
                    r=yy-f(t,*pf)
                    print(f"   {fname} slope={withslope}: x0={pf[0]:.4f} gamma={pf[1]:.4f} A={pf[2]:.2f} off={pf[3]:.2f} rmse={r.std():.2f}")
                except Exception as e:
                    print("   fail",fname,withslope,e)
