import numpy as np
from scipy.optimize import curve_fit
raw=np.loadtxt('graphene.dat',delimiter='\t',converters={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))})
x,y=raw[:,0],raw[:,1]; w=1e7/x
o=np.argsort(w); w=w[o]; y=y[o]

def make_model(order):
    def f(t,x0,g,A,*coef):
        base=sum(c*(t-x0)**k for k,c in enumerate(coef))
        return base + A*(g/2)**2/((t-x0)**2+(g/2)**2)
    return f

for name,center in [('G',1580.5),('2D',2670.3)]:
    print("########",name)
    for half in ([50,65,80,100] if name=='G' else [60,80,100,120,150]):
        lo,hi=center-half,center+half
        m=(w>=lo)&(w<=hi); t=w[m]; yy=y[m]
        for order in [1,2,3]:
            f=make_model(order)
            p0=[center,17 if name=='G' else 37, (8000 if name=='G' else 12000)] + [ (5600 if name=='G' else 1600) ] + [0]*(order-1)
            try:
                pf,cov=curve_fit(f,t,yy,p0=p0,maxfev=200000)
                r=yy-f(t,*pf)
                print(f"half={half:3d} order={order}: x0={pf[0]:8.3f} gFWHM={pf[1]:7.3f} A={pf[2]:9.1f} off={pf[3]:8.1f} rmse={r.std():7.2f}")
            except Exception as e:
                print("fail",half,order,e)
