import numpy as np
from scipy.optimize import curve_fit
raw=np.loadtxt('graphene.dat',delimiter='\t',converters={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))})
x,y=raw[:,0],raw[:,1]; w=1e7/x
o=np.argsort(w); w=w[o]; y=y[o]
def model(t,x0,g,A,off,slope,quad,shape):
    base=off+slope*(t-x0)+quad*(t-x0)**2
    if shape=='lor': peak=A*(g/2)**2/((t-x0)**2+(g/2)**2)
    elif shape=='gauss': peak=A*np.exp(-4*np.log(2)*(t-x0)**2/g**2)
    else: # pseudo-voigt eta
        lor=(g/2)**2/((t-x0)**2+(g/2)**2)
        gau=np.exp(-4*np.log(2)*(t-x0)**2/g**2)
        peak=A*(eta*lor+(1-eta)*gau)
    return base+peak
for name,center,g0,A0,o0,sl0,half in [('G',1580.4,17.5,8300,5700,-5,80),('2D',2670.2,37,12500,1700,-2,110)]:
    print("###",name)
    for shape in ['lor','gauss']:
        f=lambda t,x0,g,A,off,slope,quad: model(t,x0,g,A,off,slope,quad,shape)
        for order in [0,1,2]:
            # order: number of background terms beyond const
            if order==0:
                ff=f
                p0=[center,g0,A0,o0,0,0]
            elif order==1:
                def ff(t,x0,g,A,off,slope):
                    return model(t,x0,g,A,off,slope,0,shape)
                p0=[center,g0,A0,o0,sl0]
            else:
                ff=f; p0=[center,g0,A0,o0,sl0,0]
            m=(w>=center-half)&(w<=center+half); t=w[m]; yy=y[m]
            try:
                pf,_=curve_fit(ff,t,yy,p0=p0,maxfev=300000)
                r=yy-ff(t,*pf)
                print(f"{shape} bg{order}: x0={pf[0]:.4f} g={pf[1]:.4f} A={pf[2]:.2f} off={pf[3]:.2f} slope={pf[4] if len(pf)>4 else 0:.4f} quad={pf[5] if len(pf)>5 else 0:.2e} rmse={r.std():.2f}")
            except Exception as e:
                print("fail",shape,order,e)
